import requests, gzip, io, csv
rsids={'rs1150779','rs6909732','rs2483211','rs7742369','rs4308051','rs2871960','rs224333'}
for name in ['AFR','EAS','SAS','HIS','EUR','ALL']:
    url=f'https://cnsgenomics.com/data/giant_2022/GIANT_HEIGHT_YENGO_2022_GWAS_SUMMARY_STATS_{name}.gz'
    print('\\n', name)
    data=requests.get(url, timeout=120).content
    found={}
    with gzip.GzipFile(fileobj=io.BytesIO(data)) as gz:
        text=io.TextIOWrapper(gz)
        reader=csv.DictReader(text, delimiter='\\t')
        print('header', reader.fieldnames)
        for row in reader:
            rs=row.get('RSID')
            if rs in rsids:
                found[rs]=row
                if len(found)==len(rsids): break
    for rs in sorted(rsids):
        row=found.get(rs)
        if not row: print(rs, 'missing')
        else: print(rs, row.get('SNPID'), row.get('EFFECT_ALLELE'), row.get('OTHER_ALLELE'), row.get('EFFECT_ALLELE_FREQ'), row.get('BETA'), row.get('SE'), row.get('P'), row.get('N'))
PY"

