import json, urllib.request
rsids=['rs1150779','rs6909732','rs2483211','rs7742369','rs4308051','rs8094261','rs7235010','rs4800455','rs7244739','rs2871960','rs6918981','rs9846396','rs4800451','rs206919','rs6930978','rs611928','rs464553','rs206936','rs6912971','rs224333','rs2011603','rs7236130','rs724577','rs3791679','rs4911496','rs1415774','rs6087704','rs9435734','rs798485','rs798490','rs1812175']
base='https://www.ebi.ac.uk/gwas/rest/api/'
seen={}
for rs in rsids:
    try:
        with urllib.request.urlopen(base+'associations?rsId='+rs, timeout=20) as f: obj=json.load(f)
    except Exception as e:
        print(rs,'ERROR',e); continue
    ass=obj.get('_embedded',{}).get('associations',[])
    rows=[]
    for a in ass:
        aid=a.get('_links',{}).get('self',{}).get('href','').rstrip('/').split('/')[-1]
        if not aid: continue
        try:
            with urllib.request.urlopen(base+'associations/'+aid+'/study',timeout=20) as f: st=json.load(f)
            pi=st.get('publicationInfo',{}) or {}
            rows.append((a.get('pvalueMantissa'),a.get('pvalueExponent'),st.get('accessionId'),st.get('trait'),pi.get('pubmedId'),pi.get('title')))
        except Exception: pass
    if rows:
        print('\\n'+rs)
        for row in rows[:20]: print('\\t'.join('' if x is None else str(x) for x in row))
PY"

